{"foils":[{"nl":"Reduce the 10x36 input to a 2x7 output by taking the seven nonzero column counts and arranging them in two rows.","code":"def transform(grid):
    cols=[sum(x!=0 for x in row) for row in zip(*grid)]
    vals=[x for x in cols if x]
    vals=(vals+[0]*14)[:14]
    return [vals[:7], vals[7:14]]"},{"nl":"Crop the smallest nonzero bounding box, then resize it to 2x7 by nearest-neighbor sampling.","code":"def transform(grid):
    pts=[(i,j) for i,row in enumerate(grid) for j,x in enumerate(row) if x]
    if not pts:return [[0]*7 for _ in range(2)]
    a,b=min(i for i,j in pts),max(i for i,j in pts); c,d=min(j for i,j in pts),max(j for i,j in pts)
    return [[grid[a+(r*(b-a))//1//1 if False else a+round(r*(b-a)/1)][c+round(k*(d-c)/6)] for k in range(7)] for r in range(2)]"},{"nl":"Extract the two rows and seven columns containing the first fourteen marked cells, preserving their colors.","code":"def transform(grid):
    pts=[(i,j) for i,row in enumerate(grid) for j,x in enumerate(row) if x]
    pts=(pts+[(0,0)]*14)[:14]
    return [[grid[i][j] for i,j in pts[:7]],[grid[i][j] for i,j in pts[7:14]]]"},{"nl":"Partition the input into a 2-by-7 array of 5-by-? blocks and output the most frequent nonzero color in each block.","code":"def transform(grid):
    h,w=len(grid),len(grid[0]); out=[]
    for r in range(2):
        row=[]
        for c in range(7):
            vals=[grid[i][j] for i in range(r*h//2,(r+1)*h//2) for j in range(c*w//7,(c+1)*w//7) if grid[i][j]]
            row.append(max(set(vals),key=vals.count) if vals else 0)
        out.append(row)
    return out"},{"nl":"Return the colors at the centers of fourteen equal input partitions, arranged as 2x7.","code":"def transform(grid):
    h,w=len(grid),len(grid[0]); return [[grid[(r*h//2+(r+1)*h//2-1)//2][(c*w//7+(c+1)*w//7-1)//2] for c in range(7)] for r in range(2)]"},{"nl":"Take the first two rows and compress each into seven equal-width majority-color cells.","code":"def transform(grid):
    out=[]
    for r in range(2):
        row=[]
        for c in range(7):
            v=grid[r][c*len(grid[0])//7:(c+1)*len(grid[0])//7]
            row.append(max(set(v),key=v.count))
        out.append(row)
    return out"},{"nl":"Take the last two rows and compress each into seven equal-width majority-color cells.","code":"def transform(grid):
    out=[]; h,w=len(grid),len(grid[0])
    for r in range(2):
        row=[]
        for c in range(7):
            v=grid[h-2+r][c*w//7:(c+1)*w//7]; row.append(max(set(v),key=v.count))
        out.append(row)
    return out"},{"nl":"Use the top-left cell of each of fourteen equal rectangular input blocks as the 2x7 output.","code":"def transform(grid):
    h,w=len(grid),len(grid[0]); return [[grid[r*h//2][c*w//7] for c in range(7)] for r in range(2)]"},{"nl":"Use the bottom-right cell of each of fourteen equal rectangular input blocks as the 2x7 output.","code":"def transform(grid):
    h,w=len(grid),len(grid[0]); return [[grid[(r+1)*h//2-1][(c+1)*w//7-1] for c in range(7)] for r in range(2)]"},{"nl":"Output a 2x7 binary image indicating whether each equal input block contains any nonzero cell.","code":"def transform(grid):
    h,w=len(grid),len(grid[0]); return [[int(any(grid[i][j]!=0 for i in range(r*h//2,(r+1)*h//2) for j in range(c*w//7,(c+1)*w//7))) for c in range(7)] for r in range(2)]"}]}

